using System;using System.Collections.Generic;using System.Drawing;using System.Drawing.Drawing2D;using System.IO;using System.Windows.Forms;

public sealed class ThemePalette {
    public readonly string Id,Name;public readonly Color Outer,Paper,Surface,Soft,Ink,Muted,Accent,Border,OuterTop,OuterBottom;
    public bool IsDark {get{return Paper.GetBrightness()<.3f;}}
    public Color Today {get{return IsDark?Color.FromArgb(255,112,119):Color.FromArgb(226,73,70);}}
    public Color Danger {get{return IsDark?Color.FromArgb(255,139,139):Color.FromArgb(190,66,66);}}
    public ThemePalette(string id,string name,Color outer,Color paper,Color surface,Color soft,Color ink,Color muted,Color accent,Color border,Color top,Color bottom){Id=id;Name=name;Outer=outer;Paper=paper;Surface=surface;Soft=soft;Ink=ink;Muted=muted;Accent=accent;Border=border;OuterTop=top;OuterBottom=bottom;}
}
