public static class BlueTheme {
    static ThemePalette active=Themes.All[0];public static string CurrentId {get{return active.Id;}}public static bool IsDark {get{return active.IsDark;}}
    public static Color Outer {get{return active.Outer;}}public static Color Paper {get{return active.Paper;}}public static Color Surface {get{return active.Surface;}}public static Color Soft {get{return active.Soft;}}public static Color Ink {get{return active.Ink;}}public static Color Muted {get{return active.Muted;}}public static Color Accent {get{return active.Accent;}}public static Color Border {get{return active.Border;}}public static Color OuterTop {get{return active.OuterTop;}}public static Color OuterBottom {get{return active.OuterBottom;}}public static Color Today {get{return active.Today;}}public static Color Danger {get{return active.Danger;}}
    public static Color OuterAt(float t){t=Math.Max(0,Math.Min(1,t));return Color.FromArgb((int)Math.Round(OuterTop.R+(OuterBottom.R-OuterTop.R)*t),(int)Math.Round(OuterTop.G+(OuterBottom.G-OuterTop.G)*t),(int)Math.Round(OuterTop.B+(OuterBottom.B-OuterTop.B)*t));}
    public static void Apply(string id){ThemePalette next=Themes.Find(id);if(next.Id==active.Id)return;ThemePalette previous=active;active=next;List<Form> forms=new List<Form>();foreach(Form form in Application.OpenForms)forms.Add(form);foreach(Form form in forms){Retint(form,previous,next);PanelForm panel=form as PanelForm;if(panel!=null)panel.RefreshThemeView();}}
    static Color Map(Color value,ThemePalette previous,ThemePalette next){Color[] before={previous.Outer,previous.Paper,previous.Surface,previous.Soft,previous.Ink,previous.Muted,previous.Accent,previous.Border,previous.Today,previous.Danger};Color[] after={next.Outer,next.Paper,next.Surface,next.Soft,next.Ink,next.Muted,next.Accent,next.Border,next.Today,next.Danger};for(int i=0;i<before.Length;i++)if(value.ToArgb()==before[i].ToArgb())return after[i];return value;}
    static void Retint(Control control,ThemePalette previous,ThemePalette next){control.BackColor=Map(control.BackColor,previous,next);control.ForeColor=Map(control.ForeColor,previous,next);foreach(Control child in control.Controls)Retint(child,previous,next);control.Invalidate();}
    static bool Same(Color c,byte r,byte g,byte b){return c.R==r&&c.G==g&&c.B==b;}
    static bool NearGradient(byte r,byte g,byte b){float dr=OuterBottom.R-OuterTop.R,dg=OuterBottom.G-OuterTop.G,db=OuterBottom.B-OuterTop.B;float denominator=dr*dr+dg*dg+db*db;if(denominator==0)return Same(OuterTop,r,g,b);float t=((r-OuterTop.R)*dr+(g-OuterTop.G)*dg+(b-OuterTop.B)*db)/denominator;if(t<-.05f||t>1.05f)return false;Color expected=OuterAt(t);return Math.Abs(r-expected.R)<=2&&Math.Abs(g-expected.G)<=2&&Math.Abs(b-expected.B)<=2;}
    public static bool IsBackground(byte r,byte g,byte b){if(Same(Ink,r,g,b)||Same(Muted,r,g,b)||Same(Accent,r,g,b)||Same(Today,r,g,b)||Same(Color.White,r,g,b))return false;return Same(Outer,r,g,b)||Same(Paper,r,g,b)||Same(Surface,r,g,b)||Same(Soft,r,g,b)||Same(Border,r,g,b)||NearGradient(r,g,b);}
}
public class ThemeCard:Button {
    public readonly ThemePalette Palette;readonly Func<string> selected;
    public ThemeCard(ThemePalette palette,Func<string> choice){Palette=palette;selected=choice;Text=palette.Name;Cursor=Cursors.Hand;AccessibleName=palette.Name;SetStyle(ControlStyles.UserPaint|ControlStyles.AllPaintingInWmPaint|ControlStyles.OptimizedDoubleBuffer,true);}
    protected override void OnPaint(PaintEventArgs e){Graphics g=e.Graphics;g.SmoothingMode=SmoothingMode.AntiAlias;g.Clear(BlueTheme.Paper);bool active=selected()==Palette.Id;using(GraphicsPath box=PaperShapes.Rounded(new RectangleF(1,1,Width-3,Height-3),14))using(Brush background=new SolidBrush(Palette.Surface))using(Pen outline=new Pen(active?Palette.Accent:Palette.Border,active?2:1)){g.FillPath(background,box);g.DrawPath(outline,box);}using(Font font=Typography.Chinese(15,FontStyle.Regular))using(Brush ink=new SolidBrush(Palette.Ink))Typography.DrawString(g,Palette.Name,font,ink,14,12);Color[] colors={Palette.Outer,Palette.Soft,Palette.Accent};for(int i=0;i<colors.Length;i++)using(Brush swatch=new SolidBrush(colors[i]))g.FillEllipse(swatch,14+i*26,47,18,18);if(active)using(Font font=Typography.Chinese(11,FontStyle.Regular))using(Brush ink=new SolidBrush(Palette.Accent))Typography.DrawString(g,"已选",font,ink,Width-42,50);if(Focused)ControlPaint.DrawFocusRectangle(g,new Rectangle(6,6,Width-13,Height-13));}
}
public class ThemePicker:UtilityForm {
    readonly List<ThemeCard> cards=new List<ThemeCard>();readonly Label error;
    public ThemePicker(Func<string> selected,Func<string,bool> choose){Text="主题配色";Icon=AppIcons.Main;AutoScaleMode=AutoScaleMode.None;FormBorderStyle=FormBorderStyle.None;StartPosition=FormStartPosition.CenterScreen;ShowInTaskbar=false;ClientSize=new Size(400,438);BackColor=BlueTheme.Paper;ForeColor=BlueTheme.Ink;
        Controls.Add(new MixedLabel{Text="主题配色",Location=new Point(24,22),Size=new Size(250,32),Font=Typography.Chinese(22,FontStyle.Regular),ForeColor=BlueTheme.Ink});Controls.Add(new MixedLabel{Text="点击切换，自动保存；透明度保持不变",Location=new Point(24,66),Size=new Size(352,24),Font=Typography.Chinese(12,FontStyle.Regular),ForeColor=BlueTheme.Muted});
        Button done=new EditorDoneButton{Text="完成",Location=new Point(320,20),Size=new Size(56,32),Font=Typography.Chinese(15,FontStyle.Regular)};done.Click+=delegate{Close();};Controls.Add(done);AcceptButton=done;KeyPreview=true;KeyDown+=delegate(object sender,KeyEventArgs e){if(e.KeyCode==Keys.Escape)Close();};
        error=new MixedLabel{Location=new Point(24,402),Size=new Size(352,26),Font=Typography.Chinese(12,FontStyle.Regular),ForeColor=BlueTheme.Danger};Controls.Add(error);
        for(int i=0;i<Themes.All.Length;i++){ThemePalette palette=Themes.All[i];ThemeCard card=new ThemeCard(palette,selected){Location=new Point(24+(i%2)*180,108+(i/2)*94),Size=new Size(172,82)};card.Click+=delegate{try{if(!choose(palette.Id))throw new IOException("保存失败，仍保留原主题。");error.Text="";foreach(ThemeCard item in cards)item.Invalidate();}catch(Exception ex){error.Text=ex.Message;}};cards.Add(card);Controls.Add(card);}
        using(GraphicsPath shape=PaperShapes.Rounded(new RectangleF(0,0,Width,Height),22))Region=new Region(shape);
    }
    internal void ChooseForTest(int index){cards[index].PerformClick();}
}
public static class ThemeTests {
    static void Check(bool condition,string reason){if(!condition)throw new Exception(reason);}
    public static void Run(string directory){Directory.CreateDirectory(directory);string originalTheme=BlueTheme.CurrentId;LocalJsonRepository store=new LocalJsonRepository(Path.Combine(directory,"case-"+Guid.NewGuid().ToString("N")));NoteState state=new NoteState{Note="主题测试笔记\n第二行",Goal="测试目标",Target="2026-11-01"};state.Device.BackgroundTransparencyPercent=67;store.Save(state);string originalNote=state.Note;bool allow=true;
        try{using(ThemePicker picker=new ThemePicker(delegate{return state.Device.ThemeName;},delegate(string id){if(!allow)return false;state.Device.ThemeName=id;store.Save(state);BlueTheme.Apply(id);return true;})){
            picker.Show();Application.DoEvents();foreach(Control c in picker.Controls)Check(c.Right<=picker.ClientSize.Width&&c.Bottom<=picker.ClientSize.Height,"Theme picker clipped");
            using(Bitmap bitmap=new Bitmap(picker.Width,picker.Height)){picker.DrawToBitmap(bitmap,picker.ClientRectangle);bitmap.Save(Path.Combine(directory,"主题选择预览.png"),System.Drawing.Imaging.ImageFormat.Png);}
            for(int i=0;i<Themes.All.Length;i++){picker.ChooseForTest(i);NoteState loaded=store.Load();Check(BlueTheme.CurrentId==Themes.All[i].Id&&loaded.Device.ThemeName==Themes.All[i].Id,"Selected theme did not persist");Check(loaded.Device.BackgroundTransparencyPercent==67&&loaded.Note==originalNote,"Theme change altered transparency or note");TransparencyChecks.Run(Path.Combine(directory,Themes.All[i].Id+"-alpha.txt"));}
            allow=false;picker.ChooseForTest(0);Check(BlueTheme.CurrentId=="midnight"&&store.Load().Device.ThemeName=="midnight","Failed theme save changed theme");picker.Close();
        }
        string json=File.ReadAllText(store.PathName,System.Text.Encoding.UTF8);json=System.Text.RegularExpressions.Regex.Replace(json,"(\\\"Device\\\":\\{[^}]*\\\"SchemaVersion\\\":)2",delegate(System.Text.RegularExpressions.Match m){return m.Groups[1].Value+"3";});File.WriteAllText(store.PathName,json,System.Text.Encoding.UTF8);bool refused=false;try{store.Load();}catch(UnsupportedDataVersionException){refused=true;}Check(refused,"Future device settings silently fell back to an older backup");
        }finally{BlueTheme.Apply(originalTheme);}File.WriteAllText(Path.Combine(directory,"theme-test-result.txt"),"PASS: six theme choices, immediate UI palette, persistent settings, note/transparency retention, failed-save rollback, picker bounds, all-theme alpha and future-device-format rejection. Isolated data only.");}
}
